/* BLE sensor scan is NSH `test sensor`; only overlay live telem when the
 * snapshot has a fresh sample so NSH/UI values are not wiped by empty data.
 * 2026-09-20：逻辑提到 `bicycle_runtime_sync_companion_sensors()`，主循环每拍
 * 都会调（主骑行页以前看不到传感器值），这里保留一个薄壳避免改动调用点。 */
static void map_page_apply_companion_sensors(void)
{
    bicycle_runtime_sync_companion_sensors();
}

/* 诊断用：计时两个 UI 线程定时器回调的占用（每 2 s 一行 `[ui]`，LOG_DEBUG）。
 * 目的：`[vperf]` 只覆盖地图自己的一帧，ps 里 bicycle_ui 的其余时间在这里。 */
static struct
{
    uint32_t gpx_ms;
    uint32_t pump_ms;
    uint32_t n_gpx;
    uint32_t n_pump;
    uint32_t win;
} s_ui_pf;

static void ui_pf_flush(void)
{
    uint32_t win;

    if (s_ui_pf.win == 0u) {
        s_ui_pf.win = lv_tick_get();
        return;
    }
    win = lv_tick_elaps(s_ui_pf.win);
    if (win < 2000u) {
        return;
    }
    syslog(LOG_DEBUG, "[ui] gpx=%ums/%u pump=%ums/%u win=%ums",
        (unsigned)s_ui_pf.gpx_ms, (unsigned)s_ui_pf.n_gpx,
        (unsigned)s_ui_pf.pump_ms, (unsigned)s_ui_pf.n_pump, (unsigned)win);
    s_ui_pf.gpx_ms = 0u;
    s_ui_pf.pump_ms = 0u;
    s_ui_pf.n_gpx = 0u;
    s_ui_pf.n_pump = 0u;
    s_ui_pf.win = lv_tick_get();
}
