                view->scratch, VMAP_SCRATCH_CAP);
            VMAP_PERF_T1(tile);
            VMAP_PERF_N(n_tiles);
            vmap_render_stat_get(&st, &by);
            s_pf_stores += st;
            s_pf_bytes += by;
            if (view->font) {
