/** 分桶：<=4 / <=8 / <=16 / <=32 / <=256 / >256（后两桶对着待定的上限） */
static inline void vmap_prim_note(int32_t n, uint32_t cyc)
{
    uint32_t b;

    if (n <= 4) {
        b = 0u;
    } else if (n <= 8) {
        b = 1u;
    } else if (n <= 16) {
        b = 2u;
    } else if (n <= 32) {
        b = 3u;
    } else if (n <= 256) {
        b = 4u;
    } else {
        b = 5u;
    }
    s_prim_hist[b]++;
    s_prim_cyc_n[b] += cyc;
}
