    }
}

static void draw_land_layer(vmap_canvas_t * c, vmap_feature_iter_t it,
    uint16_t extent, float base_x, float base_y, float scale,

        vmap_render_draw_thick_line(c, pts[i].x, pts[i].y, pts[j].x, pts[j].y, width, color);
    }

    for (i = 0; i < n; i++) {
